package org.apache.commons.lang3;

import org.junit.Test;
import java.io.*;
import static org.junit.Assert.*;

public class AgentBRT_Lang_13_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        // Create a simple serializable class
        class TestClass implements Serializable {
            private static final long serialVersionUID = 1L;
            String value = "test";
        }

        // Serialize the object
        byte[] serializedObject = null;
        ByteArrayOutputStream baos = null;
        ObjectOutputStream oos = null;
        try {
            baos = new ByteArrayOutputStream();
            oos = new ObjectOutputStream(baos);
            oos.writeObject(new TestClass());
            serializedObject = baos.toByteArray();
        } catch (IOException e) {
            fail("Serialization failed: " + e.getMessage());
        } finally {
            try {
                if (oos != null) oos.close();
                if (baos != null) baos.close();
            } catch (IOException e) {
                // Ignore
            }
        }

        // Custom class loader that cannot load TestClass
        ClassLoader customClassLoader = new ClassLoader() {
            @Override
            public Class<?> loadClass(String name) throws ClassNotFoundException {
                throw new ClassNotFoundException("Cannot load class: " + name);
            }
        };

        // Attempt to deserialize using ClassLoaderAwareObjectInputStream
        ByteArrayInputStream bais = null;
        SerializationUtils.ClassLoaderAwareObjectInputStream ois = null;
        try {
            bais = new ByteArrayInputStream(serializedObject);
            ois = new SerializationUtils.ClassLoaderAwareObjectInputStream(bais, customClassLoader);
            Object obj = ois.readObject();
            assertNotNull("Deserialized object should not be null", obj);
            assertTrue("Deserialized object should be instance of TestClass", obj instanceof TestClass);
        } catch (IOException e) {
            fail("Deserialization failed: " + e.getMessage());
        } catch (ClassNotFoundException e) {
            fail("Class not found during deserialization: " + e.getMessage());
        } finally {
            try {
                if (ois != null) ois.close();
                if (bais != null) bais.close();
            } catch (IOException e) {
                // Ignore
            }
        }
    }
}

